mapper.select:
SELECT mi.* FROM mission_info mi INNER JOIN permission_info p WHERE 1=1
(mi.view_level='3' OR (mi.view_level='2' AND p.type=4 AND p.type_id=mi.id AND p.rel_id=#{missionInfo.user.currSystemId}) OR (mi.view_level='1' AND p.type=4 AND p.type_id=mi.id AND p.rel_id in
#{item.id}
))
AND mi.is_loop=#{missionInfo.isLoop}
AND mi.type=#{missionInfo.type}
AND mi.name like '%'||#{missionInfo.name}||'%' concat('%',#{missionInfo.name},'%') concat('%',#{missionInfo.name},'%')
and mi.del_flag=0 and p.del_flag=0 GROUP BY mi.id

select ngi.id nodeGroupIds from nodegroup_info ngi left join node_group_rel ngr on ngi.id = ngr.group_id left join node_info ni on ngr.uuid=ni.uuid where ngi.del_flag=0 and ni.state!=2
and ngi.id in
#{nodeGroupId}
and ni.id in
#{nodeId}

select ngi.* from
mission_node_rel mnr left join nodegroup_info ngi on mnr.rel_id = ngi.id
where mnr.type=1 and ngi.del_flag=0 and mnr.mission_id=#{missionId}

select ni.* from
mission_node_rel mnr left join node_info ni on mnr.rel_id = ni.id
where mnr.type=2 and ni.state=1 and mnr.mission_id=#{missionId}
